-- supabase/sql/exam_question_bank_neet_ug_set4.sql
--
-- Fourth curated question-bank batch for 'NEET UG' (see exam_patterns_neet_ug.sql for the exam's
-- structure, and Sets 1-3 for the earlier batches -- same table/schema, no migration needed).
-- All-new questions, no overlap with Sets 1, 2, or 3.
--
-- Same format as the earlier sets: every row is format='mcq' with a single isCorrect:true option,
-- matching NEET UG's 100% single-best-response format. 16 chapters (4 each across Physics,
-- Chemistry, Botany, Zoology) each get 4 questions.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_neet_ug.sql and
-- exam_question_bank_neet_ug_set1.sql / set2.sql / set3.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Physics: Mechanics
