 '[{"text":"A population''s allele frequencies constantly change every generation","isCorrect":false},{"text":"Allele frequencies in a population remain constant (genetic equilibrium) across generations","isCorrect":true},{"text":"All individuals in a population are genetically identical","isCorrect":false},{"text":"Mutation rates increase indefinitely","isCorrect":false}]'::jsonb,
